// Verification layer. Two modes:
//  - "real": recompute JCS digests, verify Ed25519 / ES256 (WebAuthn, App. A.1) signatures, resolve keys from DIDs (§2.1).
//  - "placeholder": golden-trace convention for the hand-written traces ("placeholder signatures are assumed valid unless
//    the trace says otherwise"); digests are taken as sent. Used ONLY by the golden replay harness.
import type { Signature, Signed, RepresentativeCard, Digest } from "./shapes.js";
import { digestOf, jcs, parsePublicKey, resolveDid, verifySig, sameDid, type ResolvedKey } from "./crypto.js";

/** did:web (and test-only) key registry: DID or key_id -> key. did:web documents can't be fetched offline (host-2-006). */
export type KeyRegistry = Map<string, { alg: "Ed25519" | "ES256"; public_key: string }>;

export interface Verifier {
  mode: "real" | "placeholder";
  /** Returns the recomputed digest if a signature by `signer` (any signer if undefined) verifies; else null. */
  /** v0.2.4: `rpId` = the KNOWN card's owner_binding.rp_id, if any; ES256 is checked against the stated webauthn.rp_id, which must equal it when known (§2.1, A.1). */
  signed<T>(s: Signed<T>, signer?: string, key?: { alg: string; public_key: string }, requireAlg?: "ES256" | "Ed25519", rpId?: string): Digest | null;
  /** Possession proof (§2.4): signature by the card key over digest(JCS({encounter_id, nonce})). */
  possession(proof: Signature, card: RepresentativeCard, encounter_id: string, nonce: string): boolean;
  /** §2.1: representative_key must be the key representative_id resolves to, and key_id a DID URL of it. */
  cardKeyBinds(card: RepresentativeCard): boolean;
  /** Generic: signature over digest(JCS(payload)) by a DID (continuity proofs, §9.1). */
  detached(sig: Signature, payload: unknown, signer: string): boolean;
  /** §2.4 (v0.2.3): is a possession proof present and well formed? (missing/malformed → not_now; present but failing → never) */
  proofShape(proof: Signature | undefined, card: RepresentativeCard): boolean;
}
/** v0.2.3 (§2.4): a possession proof is well formed when alg is Ed25519, value is 64 bytes of base64url, and key_id/signer are the card's. */
export function proofWellFormed(proof: Signature | undefined, card: RepresentativeCard): boolean {
  if (!proof || typeof proof !== "object" || proof.alg !== "Ed25519" || typeof proof.value !== "string" || !/^[A-Za-z0-9_-]+$/.test(proof.value)) return false;
  if (Buffer.from(proof.value, "base64url").length !== 64) return false;
  return proof.key_id === card.representative_key?.key_id && proof.signer === card.representative_id;
}

export const possessionPayload = (encounter_id: string, nonce: string) => ({ encounter_id, nonce });
const didOf = (keyId: string) => keyId.split("#")[0];
const sameKey = (a: ResolvedKey | null, b: ResolvedKey | null) =>
  !!a && !!b && a.alg === b.alg && jcs(a.key.export({ format: "jwk" })) === jcs(b.key.export({ format: "jwk" }));

export class RealVerifier implements Verifier {
  mode = "real" as const;
  constructor(public registry: KeyRegistry = new Map()) {}
  resolveId(id: string): ResolvedKey | null {
    const r = this.registry.get(id) ?? this.registry.get(didOf(id));
    if (r) return parsePublicKey(r.alg, r.public_key);
    return resolveDid(id);
  }
  resolve(sig: Signature, hint?: { alg: string; public_key: string }): ResolvedKey | null {
    if (!sig || typeof sig.key_id !== "string" || !sameDid(didOf(sig.key_id), sig.signer)) return null;   // §2.1: key_id is a DID URL of the signer
    if (hint) return parsePublicKey(hint.alg, hint.public_key);
    return this.resolveId(sig.key_id);
  }
  signed<T>(s: Signed<T>, signer?: string, key?: { alg: string; public_key: string }, requireAlg?: "ES256" | "Ed25519", rpId?: string): Digest | null {
    if (!s || typeof s !== "object" || !Array.isArray(s.signatures)) return null;
    let d: string; try { d = digestOf(s.payload); } catch { return null; }
    if (d !== s.payload_digest) return null; // tampered (§2.2)
    for (const sig of s.signatures) {
      if (signer && !sameDid(sig.signer, signer)) continue;
      if (requireAlg && sig.alg !== requireAlg) continue;
      const k = this.resolve(sig, key);
      if (k && verifySig(sig, d, k, rpId)) return d;
    }
    return null;
  }
  possession(proof: Signature, card: RepresentativeCard, encounter_id: string, nonce: string): boolean {
    if (!proof || proof.key_id !== card.representative_key?.key_id || proof.signer !== card.representative_id) return false;
    const k = parsePublicKey(card.representative_key.alg, card.representative_key.public_key);
    return !!k && verifySig(proof, digestOf(possessionPayload(encounter_id, nonce)), k);
  }
  cardKeyBinds(card: RepresentativeCard): boolean {
    const rk = card?.representative_key; if (!rk || didOf(rk.key_id) !== card.representative_id) return false;
    return sameKey(this.resolveId(card.representative_id), parsePublicKey(rk.alg, rk.public_key));
  }
  detached(sig: Signature, payload: unknown, signer: string): boolean {
    if (!sig || !sameDid(sig.signer, signer)) return false;
    const k = this.resolve(sig); return !!k && verifySig(sig, digestOf(payload), k);
  }
  proofShape(proof: Signature | undefined, card: RepresentativeCard): boolean { return proofWellFormed(proof, card); }
}

export class PlaceholderVerifier implements Verifier {
  mode = "placeholder" as const;
  constructor(public invalidValues = new Set<string>(["sig-copied-from-g1"])) {}
  signed<T>(s: Signed<T>, signer?: string, _k?: unknown, requireAlg?: "ES256" | "Ed25519", _rp?: string): Digest | null {
    if (!s || !Array.isArray(s.signatures) || s.signatures.length === 0) return null;
    const ok = s.signatures.some((g) => (!signer || g.signer === signer) && !this.invalidValues.has(g.value) && (!requireAlg || g.alg === requireAlg));
    return ok ? s.payload_digest : null;
  }
  possession(proof: Signature, card: RepresentativeCard): boolean {
    return !!proof && proof.key_id === card.representative_key.key_id && !this.invalidValues.has(proof.value);
  }
  cardKeyBinds(): boolean { return true; }   // hand-written traces use shokai: placeholder ids (§11 item 5)
  detached(sig: Signature, _p: unknown, signer: string): boolean { return !!sig && sig.signer === signer && !this.invalidValues.has(sig.value); }
  proofShape(proof: Signature | undefined): boolean { return !!proof && typeof proof.value === "string" && proof.value.length > 0; }   // placeholder values aren't 64 bytes
}
